function wordOverlap(claimWords, lineWords) {
    var lineSet = {};
    for (var i = 0; i < lineWords.length; i++) lineSet[lineWords[i]] = true;
    var inter = 0;
    for (var j = 0; j < claimWords.length; j++) {
